before:
/* Explicit owner request: leaves now cover the whole site, including games.
   A fixed inert sibling layer never changes layout, focus, inputs or game state.
   Ten reusable SVG backgrounds, transform-only CSS motion, no timer/JS/DOM churn.
   Overflow is clipped on the decorative layer itself, never on a game ancestor. */
body > .platform-leaf-layer{position:fixed;inset:0;z-index:3;overflow:hidden;pointer-events:none;user-select:none;contain:strict}
body > .platform-leaf-layer > .platform-leaf{position:absolute;top:-48px;width:22px;height:30px;pointer-events:none;background:url("platform-assets/leaf-sage.svg") center/contain no-repeat;opacity:.32;animation:platform-leaf-fall 24s linear infinite}
body > .platform-leaf-layer > .platform-leaf:nth-child(1){left:2%;width:16px;height:22px;opacity:.28;animation-duration:23s;animation-delay:-3s}
body > .platform-leaf-layer > .platform-leaf:nth-child(2){left:12%;width:32px;height:38px;opacity:.18;background-image:url("platform-assets/leaf-honey.svg");animation-duration:29s;animation-delay:-17s}
body > .platform-leaf-layer > .platform-leaf:nth-child(3){left:22%;width:21px;height:29px;opacity:.48;background-image:url("platform-assets/leaf-clay.svg");animation-duration:21s;animation-delay:-9s}
body > .platform-leaf-layer > .platform-leaf:nth-child(4){left:32%;width:14px;height:19px;opacity:.65;animation-duration:19s;animation-delay:-14s}
body > .platform-leaf-layer > .platform-leaf:nth-child(5){left:43%;width:38px;height:46px;opacity:.2;background-image:url("platform-assets/leaf-clay.svg");animation-duration:33s;animation-delay:-6s}
body > .platform-leaf-layer > .platform-leaf:nth-child(6){left:53%;width:24px;height:29px;opacity:.38;background-image:url("platform-assets/leaf-honey.svg");animation-duration:25s;animation-delay:-20s}
body > .platform-leaf-layer > .platform-leaf:nth-child(7){left:64%;width:18px;height:25px;opacity:.58;animation-duration:22s;animation-delay:-11s}
body > .platform-leaf-layer > .platform-leaf:nth-child(8){left:74%;width:30px;height:36px;opacity:.24;background-image:url("platform-assets/leaf-honey.svg");animation-duration:28s;animation-delay:-4s}
body > .platform-leaf-layer > .platform-leaf:nth-child(9){left:84%;width:20px;height:28px;opacity:.45;background-image:url("platform-assets/leaf-clay.svg");animation-duration:24s;animation-delay:-18s}
body > .platform-leaf-layer > .platform-leaf:nth-child(10){left:94%;width:26px;height:35px;opacity:.32;animation-duration:30s;animation-delay:-12s}
@keyframes platform-leaf-fall{
 0%{transform:translate3d(0,-48px,0) rotate(-25deg)}
 25%{transform:translate3d(-12px,calc(25vh - 12px),0) rotate(20deg)}
 50%{transform:translate3d(12px,calc(50vh + 24px),0) rotate(65deg)}
 75%{transform:translate3d(-8px,calc(75vh + 60px),0) rotate(95deg)}
 100%{transform:translate3d(18px,calc(100vh + 96px),0) rotate(135deg)}
}
@media(prefers-reduced-motion:reduce){
 body > .platform-leaf-layer{display:none}
 body > .platform-leaf-layer > .platform-leaf{animation:none}
}

after:
/* Owner-authorized document decoration. The body only establishes a containing
   block; no size, typography, overflow or game styles are changed. The inert
   sibling clips itself and follows dynamic document height without JS. */
body:has(> .platform-leaf-layer){position:relative}
body > .platform-leaf-layer{position:absolute;inset:0;z-index:3;overflow:hidden;pointer-events:none;user-select:none;contain:strict;container-type:size}
body > .platform-leaf-layer::before,body > .platform-leaf-layer::after{content:"";position:absolute;top:0;width:38%;max-width:420px;height:22px;pointer-events:none;background:url("platform-assets/tree-canopy.svg") left top/100% 22px no-repeat;opacity:.62}
body > .platform-leaf-layer::before{left:0}
body > .platform-leaf-layer::after{right:0;background-position:right top;opacity:.42}
body > .platform-leaf-layer > .platform-leaf{position:absolute;top:-48px;width:22px;height:30px;pointer-events:none;background:url("platform-assets/leaf-sage.svg") center/contain no-repeat;opacity:.32;animation:platform-leaf-fall 140s linear infinite}
body > .platform-leaf-layer > .platform-leaf:nth-child(1){left:3%;width:16px;height:22px;opacity:.28;animation-duration:130s;animation-delay:-14s}
body > .platform-leaf-layer > .platform-leaf:nth-child(2){left:20%;width:32px;height:38px;opacity:.18;background-image:url("platform-assets/leaf-honey.svg");animation-duration:165s;animation-delay:-96s}
body > .platform-leaf-layer > .platform-leaf:nth-child(3){left:38%;width:21px;height:29px;opacity:.4;background-image:url("platform-assets/leaf-clay.svg");animation-duration:120s;animation-delay:-49s}
body > .platform-leaf-layer > .platform-leaf:nth-child(4){left:56%;width:14px;height:19px;opacity:.45;animation-duration:110s;animation-delay:-80s}
body > .platform-leaf-layer > .platform-leaf:nth-child(5){left:74%;width:38px;height:46px;opacity:.2;background-image:url("platform-assets/leaf-clay.svg");animation-duration:180s;animation-delay:-30s}
body > .platform-leaf-layer > .platform-leaf:nth-child(6){left:92%;width:24px;height:29px;opacity:.38;background-image:url("platform-assets/leaf-honey.svg");animation-duration:145s;animation-delay:-110s}
/* A quieter distant plane follows the viewport; six foreground leaves stay
   anchored to the document. Ten leaves total, no cursor/scroll event listeners. */
body > .platform-leaf-foreground{position:fixed;inset:0;z-index:3;overflow:hidden;pointer-events:none;user-select:none;contain:strict;container-type:size}
body > .platform-leaf-foreground > .platform-leaf{position:absolute;top:-48px;pointer-events:none;width:14px;height:19px;opacity:.18;background:url("platform-assets/leaf-sage.svg") center/contain no-repeat;animation:platform-leaf-fall 35s linear infinite}
body > .platform-leaf-foreground > .platform-leaf:nth-child(1){left:7%;animation-delay:-8s}
body > .platform-leaf-foreground > .platform-leaf:nth-child(2){left:33%;width:22px;height:28px;opacity:.22;background-image:url("platform-assets/leaf-honey.svg");animation-duration:40s;animation-delay:-26s}
body > .platform-leaf-foreground > .platform-leaf:nth-child(3){left:66%;width:16px;height:22px;opacity:.3;background-image:url("platform-assets/leaf-clay.svg");animation-duration:30s;animation-delay:-15s}
body > .platform-leaf-foreground > .platform-leaf:nth-child(4){left:91%;width:24px;height:30px;opacity:.15;animation-duration:38s;animation-delay:-33s}
@keyframes platform-leaf-fall{
 0%{transform:translate3d(0,-48px,0) rotate(-25deg)}
 25%{transform:translate3d(-12px,calc(25cqh - 12px),0) rotate(20deg)}
 50%{transform:translate3d(12px,calc(50cqh + 24px),0) rotate(65deg)}
 75%{transform:translate3d(-8px,calc(75cqh + 60px),0) rotate(95deg)}
 100%{transform:translate3d(18px,calc(100cqh + 96px),0) rotate(135deg)}
}
@media(prefers-reduced-motion:reduce){
 body > .platform-leaf-foreground > .platform-leaf{display:none;animation:none}
 body > .platform-leaf-layer > .platform-leaf{display:none;animation:none}
}
